                    "sql": "create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_PandL as select SALEORDERITEMCODE ,a.source as Marketing_Source ,(a.channel) as Marketing_Channel ,a.marketplace ,a.FINAL_MARKETPLACE ,(a.order_Date::date) as Date ,a.order_id ,a.reference_code ,a.shop_name ,a.return_flag ,location_key ,a.new_customer_flag ,a.customer_id_final ,payment_mode ,payment_gateway ,a.awb ,a.order_Status ,a.shipping_status ,a.final_shipping_status ,case when lower(order_Status) like \'%cancel%\' then upper(order_status) else upper(coalesce(final_shipping_status,order_status)) end final_status ,a.sku ,(a.sku_code) sku_code ,a.common_sku_code ,a.product_name_final PRODUCT_NAME_FINAL ,a.product_sub_category product_sub_category ,a.product_category PRODUCT_CATEGORY ,a.quantity ,d.gst ,a.return_amount ,a.total_mrp ,a.selling_price ,a.shipping_price shipping_price ,d.cogs as test_cogs ,case when lower(a.type) like \'%sale%\' then (ifnull(d.cogs,0)*ifnull(quantity,0)) else -1*(ifnull(d.cogs,0)*ifnull(ex_RETURNED_QUANTITY,0)) end as COGS ,a.tax tax ,a.RETURN_TAX ,a.type ,null as Spend ,case when a.new_customer_flag = \'Repeat\' then LAG(a.order_date) IGNORE NULLS OVER (partition by a.customer_id_final ORDER BY a.order_date) end previous_date ,datediff(day,previous_date,a.order_Date) days_from_last_order ,otherShipmentCost ,logisticCost ,otheroperationcosts ,paymentgatewaycharges ,marketplaceCommission ,div0(ifnull(EBO_Rent,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_Rent ,div0(ifnull(EBO_salary,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_salary ,div0(ifnull(EBO_overhead,0),count(*) over(partition by lower(location_key),last_day(to_date(a.order_date)),lower(a.type))) as EBO_overhead ,FINAL_Mapped_Marketplace ,a.EBO_Store from ( select *, coalesce(ebo_Marketplace,upper(case when lower(marketplace) like \'%amazon%\' then \'AMAZON\' when lower(marketplace) like \'%flipkart%\' then \'FLIPKART\' when lower(marketplace) like any (\'%shopify%\',\'%woocomm%\') then \'WEBSITE\' when lower(marketplace) like \'%myntra%\' then \'MYNTRA\' when lower(marketplace) like \'%pepperfry%\' then \'PEPPERFRY\' else marketplace END)) as FINAL_Mapped_Marketplace, coalesce(ebo_Marketplace,case when lower(marketplace) like \'%amazon%\' then \'AMAZON\' when lower(marketplace) like \'%flipkart%\' then \'FLIPKART\' when lower(marketplace) like any (\'%shopify%\',\'%woocomm%\') then \'WEBSITE\' when lower(marketplace) like \'%myntra%\' then \'MYNTRA\' when lower(marketplace) like \'%pepperfry%\' then \'PEPPERFRY\' else \'OTHERS\' END) as FINAL_MARKETPLACE, coalesce(ebo_Marketplace,case when lower(marketplace) like \'%amazon%\' then \'AMAZON\' when lower(marketplace) like \'%flipkart%\' then \'FLIPKART\' when lower(marketplace) like any (\'%shopify%\',\'%woocomm%\') then \'WEBSITE\' when lower(marketplace) like any (\'%zepto%\',\'%instamart%\',\'%blinkit%\') then \'QC\' else marketplace END) as FINAL_MARKETPLACE_shipment_costs ,store_name as EBO_Store FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_db_sales_consolidated sc left join ( Select \"Store Seller Code on EasyEcom\" key , upper(\"Store Name\") store_name, \'EBO\' as ebo_Marketplace from sleepycat_db.maplemonk.sleepycat_db_ebo_metrics qualify row_number() over(partition by lower(trim(key)) order by 1) = 1 )eb on lower(trim(location_key)) = lower(trim(key)) where (lower(concat(reference_code,sku)) in ( ( select distinct lower(concat(reference_code,sku)) rf from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where not(lower(ORDER_STATUS) like \'%cancel%\') and not(UPPER(replace(reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\',\'R%\',\'%$R%\')) union (select distinct lower(concat(reference_code,sku)) from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where (UPPER(replace(reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\',\'R%\',\'%$R%\')) and lower(concat(SPLIT_PART(reference_code,\'_\',1),sku)) in ( select distinct lower(concat(reference_code,sku)) as sd from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where not(UPPER(replace(reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\',\'R%\',\'%$R%\')) and lower(ifnull(order_status,\'\')) like \'%cancel%\' ) ) ) ) ) or lower(type) like \'%return%\' ) a left join ( select * from (select sku_code , try_to_date(start_date,\'DD-MON-YY\') start_Date , try_to_date(end_date,\'DD-MON-YY\') End_date , try_to_double(mrp) mrp , try_to_double(cogs) cogs , div0(try_to_double(replace(gst,\'%\',\'\')),100) gst ,\'sales\' as TYPE , row_number() over (partition by sku_code, start_date, end_date order by mrp desc) rw from SLEEPYCAT_DB.MAPLEMONK.SKU_MRP_COGS ) where rw=1 ) d on lower(replace(d.sku_code,\' \',\'\')) = lower(replace(a.sku,\' \',\'\')) and to_date(a.order_date)::date >= d.start_date and to_date(a.order_date)::date <= d.end_date left join ( SELECT TO_DATE(start_date, \'DD/MM/YYYY\') AS END_DATE, TO_DATE(end_date, \'DD/MM/YYYY\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(\"Cost %\", \'%\', \'\')::float/100 AS otherShipmentCost FROM sleepycat_db.maplemonk.sleepycat_db_other_shipment_cost qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) osc on lower(a.FINAL_MARKETPLACE_shipment_costs) = lower(osc.MARKETPLACE) and to_date(a.order_date)::date >= osc.start_date and to_date(a.order_date)::date <= osc.end_date left join ( SELECT TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 AS logisticCost FROM sleepycat_db.maplemonk.sleepycat_db_logistic_costs where marketplace is not null qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) a_c on lower(a.FINAL_MARKETPLACE) = lower(a_c.MARKETPLACE) and a.order_Date::date >= a_c.START_DATE and a.order_Date::date <= a_c.END_DATE left join ( select TO_DATE(END_DATE, \'DD-Mon-YY\')END_DATE, TO_DATE(START_date, \'DD-Mon-YY\')START_DATE, upper(marketplace) marketplace, \'sales\' as TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 as otheroperationcosts from sleepycat_db.maplemonk.other_operation_costs qualify row_number() over(partition by START_DATE,END_DATE,upper(marketplace) order by 1 ) = 1 ) opc on lower(a.FINAL_MARKETPLACE) = lower(opc.MARKETPLACE) and a.order_Date::date >= opc.START_DATE and a.order_Date::date <= opc.END_DATE left join ( SELECT TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, upper(marketplace) as MARKETPLACE, \'sales\' AS TYPE, REPLACE(COMMISSION_VALUE, \'%\', \'\')::float/100 AS paymentgatewaycharges FROM sleepycat_db.maplemonk.sleepycat_db_payment_gateway_charges qualify row_number() over(partition by start_date,end_date,upper(marketplace) order by 1 ) = 1 ) pgc on trim(lower(a.FINAL_MARKETPLACE)) = trim(lower(pgc.MARKETPLACE)) and to_date(a.order_date)::date >= pgc.start_date and to_date(a.order_date)::date <= pgc.end_date left join ( select upper(marketplace) Marketplace, TO_DATE(end_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(start_date, \'YYYY-MM-DD\') AS START_DATE, \'sales\' AS TYPE, upper(category) as Category, REPLACE(\"Original Commission_Value\", \'%\', \'\')::float/100 AS marketplaceCommission FROM sleepycat_db.maplemonk.sleepycat_db_marketplace_commissions where not(lower(marketplace) like any (\'%razor%\',\'%snap%\')) qualify row_number() over(partition by start_date,end_date,upper(marketplace),upper(category) order by 1 ) = 1 )mc on lower(a.FINAL_MARKETPLACE) = lower(mc.MARKETPLACE) and to_date(a.order_date)::date >= mc.start_date and to_date(a.order_date)::date <= mc.end_date and lower(a.product_category) = lower(mc.category) left join ( select upper(\"Store Seller Code on EasyEcom\") StoreCode, TO_DATE(to_date, \'YYYY-MM-DD\') AS END_DATE, TO_DATE(from_date, \'YYYY-MM-DD\') AS START_DATE, \'sales\' AS TYPE, REPLACE(rent, \',\', \'\')::float AS EBO_Rent, REPLACE(salary, \',\', \'\')::float AS EBO_salary, REPLACE(overhead, \',\', \'\')::float AS EBO_overhead, FROM sleepycat_db.maplemonk.sleepycat_db_ebo_metrics qualify row_number() over(partition by start_date,end_date,upper(StoreCode) order by 1 ) = 1 )ebo on lower(a.location_key) = lower(ebo.StoreCode) and to_date(a.order_date)::date >= ebo.start_date and to_date(a.order_date)::date <= ebo.end_date ;",
